def rm_old_files(rootdir, excludes=None, includes=None,
                 expire_time=(30 * DAY)):
    """Nuke everything under '''rootdir''' that doesn't match
       '''exclude''' that's older than '''expire_time'''.
    """

    if excludes is None:
        excludes = []

    if includes is None:
        includes = []

    def is_wanted(path):
        return not any(fnmatch.fnmatch(path, pattern) for pattern in excludes) and \
               (not includes or any(fnmatch.fnmatch(path, pattern) for pattern in includes))

    os.chdir(rootdir)

    expiration_date = time.time() - expire_time

    for path in \
        filter(lambda e: os.stat(e).st_ctime < expiration_date and is_wanted(e),
               os.listdir('.')):
        sys.stdout.write('Removing "%s/%s"\n' % (rootdir, path, ))
        if os.path.isdir(path):
            for root, __, files, in os.walk(path, topdown=False):
                for f in files:
                    os.unlink(os.path.join(root, f))
            os.rmdir(path)
        else:
            os.unlink(path)
